window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-46f324c847b10dcc"]={"versions": [{"id": "FIG-46f324c847b10dcc", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software &amp; Systems Process Engineering Metamodel) der AUTOSAR-Methodik zur Beschreibung des Arbeitsschritts „Configure ECUC“. Der Ablauf beschreibt die Konfiguration der BSW- und Systemanteile auf Steuergeräteebene innerhalb des Integrationsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> [1]: Ausführende Rolle (<code>«performs»</code>).\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure ECUC</code>: Zentrale Transformationsaktivität.\n</li></ul>\n</li><li>Eingangs- und Ausgangsartefakte:\n<ul class=\"fig-list\"><li><code>ECU Extract</code> [1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt (Briefumschlag-Symbol mit Port-Leiste).\n</li><li><code>BSW Module Delivered Bundle</code> [0..*]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt.\n</li><li><code>AUTOSAR Standardized ECU</code>... [0..1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Dokumenten-Artefakt.\n</li><li><code>ECU Configuration Values</code> [1]: Ein- und Ausgangsartefakt (<code>«inoutput»</code>), repräsentiert als Dokumenten-Artefakt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>ECU Integrator</code> führt die Aktivität <code>Configure ECUC</code> aus. Als verbindliche Eingabe dient genau ein <code>ECU Extract</code> [1]. Parallel dazu fließen null bis beliebig viele <code>BSW Module Delivered Bundle</code> [0..*] sowie optional ein Standard-ECU-Artefakt (<code>AUTOSAR Standardized ECU...</code> [0..1]) ein. Auf Basis dieser Quellen erstellt und modifiziert die Aktivität iterativ die <code>ECU Configuration Values</code>, die sowohl als Eingangs- als auch als Ergebnisartefakt über eine bidirektionale Relation (<code>«inoutput»</code>, Kardinalität 1) angebunden sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den methodischen Ablauf der ECU-Konfiguration in AUTOSAR Classic. Werkzeugketten für ECU-Konfiguratoren müssen den Import des ECU-Extracts und der BSW-Modulpakete unterstützen. Das Artefakt <code>ECU Configuration Values</code> wird im XML-Format (ARXML) gehalten und iterativ verfeinert, bevor die BSW-Generierung nachgelagert aufgerufen werden kann.</p>"}, {"id": "FIG-6d77a999a4d99df0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software &amp; Systems Process Engineering Metamodel) der AUTOSAR-Methodik zur Beschreibung des Arbeitsschritts „Configure ECUC“. Der Ablauf beschreibt die Konfiguration der BSW- und Systemanteile auf Steuergeräteebene innerhalb des Integrationsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> [1]: Ausführende Rolle (<code>«performs»</code>).\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure ECUC</code>: Zentrale Transformationsaktivität.\n</li></ul>\n</li><li>Eingangs- und Ausgangsartefakte:\n<ul class=\"fig-list\"><li><code>ECU Extract</code> [1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt (Briefumschlag-Symbol mit Port-Leiste).\n</li><li><code>BSW Module Delivered Bundle</code> [0..*]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt.\n</li><li><code>AUTOSAR Standardized ECU</code>... [0..1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Dokumenten-Artefakt.\n</li><li><code>ECU Configuration Values</code> [1]: Ein- und Ausgangsartefakt (<code>«inoutput»</code>), repräsentiert als Dokumenten-Artefakt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>ECU Integrator</code> führt die Aktivität <code>Configure ECUC</code> aus. Als verbindliche Eingabe dient genau ein <code>ECU Extract</code> [1]. Parallel dazu fließen null bis beliebig viele <code>BSW Module Delivered Bundle</code> [0..*] sowie optional ein Standard-ECU-Artefakt (<code>AUTOSAR Standardized ECU...</code> [0..1]) ein. Auf Basis dieser Quellen erstellt und modifiziert die Aktivität iterativ die <code>ECU Configuration Values</code>, die sowohl als Eingangs- als auch als Ergebnisartefakt über eine bidirektionale Relation (<code>«inoutput»</code>, Kardinalität 1) angebunden sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den methodischen Ablauf der ECU-Konfiguration in AUTOSAR Classic. Werkzeugketten für ECU-Konfiguratoren müssen den Import des ECU-Extracts und der BSW-Modulpakete unterstützen. Das Artefakt <code>ECU Configuration Values</code> wird im XML-Format (ARXML) gehalten und iterativ verfeinert, bevor die BSW-Generierung nachgelagert aufgerufen werden kann.</p>"}, {"id": "FIG-ebe1a2bc37f6d125", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software &amp; Systems Process Engineering Metamodel) der AUTOSAR-Methodik zur Beschreibung des Arbeitsschritts „Configure ECUC“. Der Ablauf beschreibt die Konfiguration der BSW- und Systemanteile auf Steuergeräteebene innerhalb des Integrationsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rolle:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> [1]: Ausführende Rolle (<code>«performs»</code>).\n</li></ul>\n</li><li>Aktivität:\n<ul class=\"fig-list\"><li><code>Configure ECUC</code>: Zentrale Transformationsaktivität.\n</li></ul>\n</li><li>Eingangs- und Ausgangsartefakte:\n<ul class=\"fig-list\"><li><code>ECU Extract</code> [1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt (Briefumschlag-Symbol mit Port-Leiste).\n</li><li><code>BSW Module Delivered Bundle</code> [0..*]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Zustellungs-/Austauschobjekt.\n</li><li><code>AUTOSAR Standardized ECU</code>... [0..1]: Eingangsartefakt (<code>«input»</code>), repräsentiert als Dokumenten-Artefakt.\n</li><li><code>ECU Configuration Values</code> [1]: Ein- und Ausgangsartefakt (<code>«inoutput»</code>), repräsentiert als Dokumenten-Artefakt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>ECU Integrator</code> führt die Aktivität <code>Configure ECUC</code> aus. Als verbindliche Eingabe dient genau ein <code>ECU Extract</code> [1]. Parallel dazu fließen null bis beliebig viele <code>BSW Module Delivered Bundle</code> [0..*] sowie optional ein Standard-ECU-Artefakt (<code>AUTOSAR Standardized ECU...</code> [0..1]) ein. Auf Basis dieser Quellen erstellt und modifiziert die Aktivität iterativ die <code>ECU Configuration Values</code>, die sowohl als Eingangs- als auch als Ergebnisartefakt über eine bidirektionale Relation (<code>«inoutput»</code>, Kardinalität 1) angebunden sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den methodischen Ablauf der ECU-Konfiguration in AUTOSAR Classic. Werkzeugketten für ECU-Konfiguratoren müssen den Import des ECU-Extracts und der BSW-Modulpakete unterstützen. Das Artefakt <code>ECU Configuration Values</code> wird im XML-Format (ARXML) gehalten und iterativ verfeinert, bevor die BSW-Generierung nachgelagert aufgerufen werden kann.</p>"}], "trans": [{"from": "FIG-46f324c847b10dcc", "to": "FIG-6d77a999a4d99df0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6d77a999a4d99df0", "to": "FIG-ebe1a2bc37f6d125", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
